  "方案A": {
    "阅读方案": "韩立随众孩童冲进竹林，身后跟着一位瘦长师兄。竹林宽广，斜坡渐陡，他走得腿越来越重，只好借竹茎前行。实在累了便坐土堆喘息，回头见师兄纹丝不动立在下方，目光冷冷，心中害怕，又听前方有喘息声，知道有人也在休息，稍作停留便匆忙赶路。",
    "理由": "按韩立进入竹林、休息、再赶路的事件先后梳理，便于课堂对照原文复习。",
    "取舍": "略去了考核规则和七玄门背景，推迟到下一环节再讲。",
    "待问": "是否保留师兄“冷冷目光”这一细节以贴合原文氛围？"
  },
  "方案B": {
    "阅读方案": "考核路线从竹林中的小路通往炼骨崖，依次经过竹林地段、岩壁地带，最后到达山崖；正午前登顶者才能成为正式弟子，表现可圈可点者可收为记名弟子。出发前岳堂主说师兄们会在后面护住，韩立身后正有一位瘦长师兄紧跟，韩立休息时师兄仍静立守护，韩立因害怕其冷脸而继续前行。",
    "理由": "突出考核路线、截止时点和师兄保护，适合快速掌握选拔制度的关键信息。",
    "取舍": "弱化了韩立疲劳感的细致描写，将重点放在规则与保障措施上。",
    "待问": "正午前未到崖顶但表现突出者，收为记名弟子是否算过关？"
  }
}
